package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.widget.*;import java.time.*;import android.database.Cursor;
/** Shared calendar editor. Legacy date-only entries stay all-day until explicitly changed. */
final class TaskEditor {
 static ContentValues values(String title,String day,boolean allDay,String start,String end,String zone){if(title.trim().isEmpty()||title.length()>150)throw new IllegalArgumentException();if(!day.isEmpty())LocalDate.parse(day);ZoneId timezone=ZoneId.of(zone);ContentValues v=new ContentValues();v.put("title",title.trim());v.put("due",day);v.put("is_all_day",allDay?1:0);v.put("timezone",zone);v.putNull("start_at");v.putNull("end_at");if(!allDay){LocalDateTime from=LocalDateTime.parse(start),to=LocalDateTime.parse(end);if(!to.isAfter(from)||timezone.getRules().getValidOffsets(from).size()!=1||timezone.getRules().getValidOffsets(to).size()!=1)throw new IllegalArgumentException();v.put("start_at",from.toString());v.put("end_at",to.toString());v.put("due",from.toLocalDate().toString());}v.put("updated",System.currentTimeMillis());return v;}
 static EditText field(Context a,LinearLayout form,String hint,String text){EditText e=new EditText(a);e.setHint(hint);e.setSingleLine(true);e.setText(text);form.addView(e);return e;}
 static void show(GoalAgentActivity a,TaskStore store,long id,String goal,String title,String source,Runnable changed){LinearLayout form=Ui.vertical(a,NubiCompanionUi.WHITE,16);String day="",start="",end="",zone="Asia/Seoul";boolean all=true;if(id>0)try(Cursor c=store.getReadableDatabase().rawQuery("SELECT due,start_at,end_at,timezone,is_all_day FROM tasks WHERE _id=?",new String[]{Long.toString(id)})){if(c.moveToFirst()){day=c.isNull(0)?"":c.getString(0);start=c.isNull(1)?"":c.getString(1);end=c.isNull(2)?"":c.getString(2);zone=c.isNull(3)?zone:c.getString(3);all=c.getInt(4)==1;}}EditText name=field(a,form,"할 일",title),date=field(a,form,"날짜 YYYY-MM-DD (선택)",day);CheckBox whole=new CheckBox(a);whole.setText("종일");whole.setChecked(all);form.addView(whole);EditText from=field(a,form,"시작 YYYY-MM-DDTHH:mm",start),to=field(a,form,"종료 YYYY-MM-DDTHH:mm",end),tz=field(a,form,"시간대 (예: Asia/Seoul)",zone);from.setEnabled(!all);to.setEnabled(!all);whole.setOnCheckedChangeListener((button,on)->{from.setEnabled(!on);to.setEnabled(!on);});TextView scope=Ui.text(a,goal.isEmpty()?"분류되지 않은 일정":"선택한 목표에 저장",13,0xff888888,false);form.addView(scope);ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(id>0?"일정 수정":"일정 추가").setView(scroll).setNegativeButton("취소",null).setPositiveButton("저장",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{try{ContentValues data=values(name.getText().toString(),date.getText().toString().trim(),whole.isChecked(),from.getText().toString().trim(),to.getText().toString().trim(),tz.getText().toString().trim());if(id>0)store.getWritableDatabase().update("tasks",data,"_id=?",new String[]{Long.toString(id)});else{data.put("kind","목표 실행");data.put("state","대기");if(!goal.isEmpty())data.put("goal_id",goal);data.put("source_url",source);store.getWritableDatabase().insertOrThrow("tasks",null,data);}dialog.dismiss();changed.run();}catch(Exception e){name.setError("제목·날짜·시작/종료·시간대를 확인해 주세요. 종료는 시작 이후여야 해요.");}}));dialog.show();}
}
